'use strict';
window.GameData = (() => {
  const types = {
    INTJ:{name:'幕后军师',en:'THE MASTERMIND',group:'analyst',quote:'别急，这波在我计算之内。',intro:'你还没进副本，脑子里的路线已经跑完了。比起临场救火，你更喜欢提前让火烧不起来。通关不是运气好，是你把该想的都想过了。',tags:['提前三步','配装研究员','安静带飞'],habits:['看攻略时，顺手把攻略优化了。','仓库里总有一件“以后肯定用得上”的装备。','嘴上说随便，心里已经排好最优解。'],mate:'ENFP',mateText:'你负责靠谱，快乐由对方承包。'},
    INTP:{name:'机制考古学家',en:'THE THEORYCRAFTER',group:'analyst',quote:'等一下，这个机制不对劲。',intro:'别人问这关怎么过，你先问这关为什么这么设计。一个冷门机制就能让你研究一晚上。对你来说，理解游戏本身，就是另一种通关。',tags:['机制爱好者','野路子出装','脑内实验室'],habits:['测试伤害花的时间，比打怪还多。','会为一个不起眼的道具研究半天。','操作未必拉满，理论绝对管够。'],mate:'ENTJ',mateText:'你的奇思妙想，需要一个把实验开起来的人。'},
    ENTJ:{name:'天生指挥官',en:'THE SHOTCALLER',group:'analyst',quote:'都别慌，听我报点。',intro:'一群人还在讨论去哪，你已经标好点了。你擅长把散装队友拧成一支队伍，享受大家各司其职、配合拿下的瞬间。偶尔也记得问一句：大家累不累？',tags:['开团担当','目标明确','全队的脑子'],habits:['语音里总有你的战术安排。','输一局没事，不知道为什么输才难受。','团建玩游戏，最后变成你带项目。'],mate:'INTP',mateText:'你管推进，对方提供出其不意的解法。'},
    ENTP:{name:'整活发明家',en:'THE WILD CARD',group:'analyst',quote:'这套路能赢，但不够离谱。',intro:'你最怕的不是输，是每局都一个样。冷门组合、奇怪路线、朋友没见过的玩法，都值得拿一局试试。战绩可以晚点说，节目效果得先到位。',tags:['邪道速通','套路粉碎机','这也能玩'],habits:['明知不是版本答案，还是想试一把。','队友说“不可能”，你反而来劲了。','失败后第一反应是：再调一下肯定行。'],mate:'INFJ',mateText:'你负责把脑洞打开，对方能听懂你的离谱。'},
    INFJ:{name:'剧情守夜人',en:'THE STORYKEEPER',group:'diplomat',quote:'这个 NPC 后来怎么样了？',intro:'一段支线、一封没寄出的信，都可能让你惦记很久。你不只是在通关，也在和这个世界好好告别。片尾字幕出来时，别人看制作组，你还在缓一缓。',tags:['支线全清','角色观察员','长情玩家'],habits:['会记住一个没什么戏份的 NPC 的名字。','做选择前，先想谁会因此受伤。','通关以后，偶尔回旧存档看看。'],mate:'ENTP',mateText:'有人陪你认真入戏，也有人拉你试试另一条路。'},
    INFP:{name:'异世界住民',en:'THE DAYDREAMER',group:'diplomat',quote:'主线等会儿，我想看看日落。',intro:'游戏对你来说，是可以搬进去住一会儿的地方。收集一套喜欢的衣服，给房子添盏灯，再找个好看的角落发呆。进度条没怎么动，但今天过得挺好。',tags:['风景收藏家','沉浸式发呆','自己的小宇宙'],habits:['捏脸一小时，起名又半小时。','截图文件夹比装备栏丰富。','不舍得卖掉朋友送的低级小物件。'],mate:'ENFJ',mateText:'你在自己的世界里发光，对方会来敲门约你出发。'},
    ENFJ:{name:'公会大家长',en:'THE GUILD HEART',group:'diplomat',quote:'人齐了没？一个都不能少。',intro:'你组队在意的不是配置齐不齐，是人开不开心。会主动带新人，也能察觉语音里谁突然安静了。大家愿意上线，有时只是因为你也在。',tags:['新人保护伞','气氛调节员','全员通关'],habits:['背包里有给别人留的东西。','队友失误，先说“没事，再来”。','散伙前总要确认大家都拿到奖励。'],mate:'INFP',mateText:'对方让你慢一点，也有人记得照顾你。'},
    ENFP:{name:'快乐永动机',en:'THE PARTY STARTER',group:'diplomat',quote:'赢不赢另说，先笑为敬。',intro:'你一进语音，今晚的节目就开场了。新游戏要试，新朋友要认识，路过奇怪的东西也得凑过去看看。跟你玩的人通常记不清比分，但记得那晚很好笑。',tags:['气氛组组长','兴趣刷新中','朋友在哪我在哪'],habits:['一句“来都来了”开启一段新冒险。','总能把队友的失误讲成名场面。','游戏列表里有很多“下次一起玩”。'],mate:'INTJ',mateText:'你带对方出舒适区，对方帮你稳稳落地。'},
    ISTJ:{name:'人形攻略本',en:'THE RELIABLE ONE',group:'sentinel',quote:'药带了，路线也记好了。',intro:'你不一定话最多，但准备一定到位。该刷的材料、该带的补给、该踩的机制，一个都不含糊。队友一句“有你在就放心”，比稀有掉落还让你舒坦。',tags:['稳得一批','准备万全','机制零失误'],habits:['每日任务清得整整齐齐。','固定队几点开打，你提前五分钟到。','新版本上线，先看更新说明。'],mate:'ESFP',mateText:'你守住下限，对方让每次开局多一点惊喜。'},
    ISFJ:{name:'队伍补给站',en:'THE SAFE HAVEN',group:'sentinel',quote:'你们打，我背包里还有药。',intro:'你总能注意到队伍里缺了什么。有人忘带药，你递上去；有人跟不上，你等一等。你不抢聚光灯，但大家打得顺，往往有你的一份。',tags:['后勤满分','贴心辅助','细节控'],habits:['记得队友缺哪种材料。','开荒前默默把食物和药备齐。','习惯看一眼落在最后的那个人。'],mate:'ESTP',mateText:'对方敢向前冲，因为知道背后有你。'},
    ESTJ:{name:'副本项目经理',en:'THE RAID MANAGER',group:'sentinel',quote:'八点开打，别让我挨个摇人。',intro:'你擅长把“有空一起玩”变成真的一起玩。集合、分工、推进、收工，安排得明明白白。你不是非要管大家，只是实在看不得一晚上都耗在等人。',tags:['效率至上','说打就打','进度推动机'],habits:['收藏了一份能直接发群里的攻略。','任务一领，就想顺手全部做完。','组队像排课表，但真能按时通关。'],mate:'ISFP',mateText:'你带着进度走，对方提醒你沿途也有风景。'},
    ESFJ:{name:'开黑召集人',en:'THE SQUAD GLUE',group:'sentinel',quote:'缺一个，来不来？就差你了。',intro:'你的好友列表不是摆设。谁擅长什么、谁最近上线少了、谁和谁一起玩最开心，你都心里有数。你最喜欢的满编，是熟悉的人一个不少。',tags:['好友列表活地图','组队黏合剂','熟人局万岁'],habits:['有新活动第一时间发进群里。','经常为了凑齐队伍去敲人。','最怀念的版本，是朋友都在的版本。'],mate:'ISTP',mateText:'你把人叫齐，对方默默把难关解决。'},
    ISTP:{name:'沉默操作怪',en:'THE QUIET ACE',group:'explorer',quote:'话不多说，看我操作。',intro:'长篇攻略不如亲手打一把。你喜欢摸清手感，在当下做出漂亮反应。语音里也许没你多少声音，关键时刻的那一下，却能让大家集体开麦。',tags:['手比嘴快','临场反应派','安静收割'],habits:['新武器到手，先找怪试一套。','不太解释，打完大家自然就懂了。','喜欢靠自己摸到的那个小技巧。'],mate:'ESFJ',mateText:'对方负责热场和摇人，你只管把操作打出来。'},
    ISFP:{name:'佛系漫游者',en:'THE SLOW PLAYER',group:'explorer',quote:'不赶进度，今天也算上线了。',intro:'你不太爱被效率追着跑。想钓鱼就钓鱼，想装修就装修；喜欢一件装备，属性差点也能穿。玩游戏嘛，自己的舒服才是第一优先级。',tags:['审美在线','不卷进度','舒服最重要'],habits:['选装备先看好不好看。','偶尔绕远路，只因为那边有花。','今天想玩什么，上线以后再说。'],mate:'ESTJ',mateText:'有人帮你搞定麻烦的准备，你负责让旅途变好看。'},
    ESTP:{name:'头号开团手',en:'THE FIRST MOVER',group:'explorer',quote:'我先上了，你们跟上！',intro:'看到机会，你的手已经比脑子先动了。你喜欢对抗里的即时反馈，也乐于在混乱中抓住那一秒。风险确实有，但肾上腺素到位的感觉，别的换不来。',tags:['行动力拉满','先打再说','高光制造机'],habits:['队友还在商量，你已经到点了。','残血反杀的录像会反复看。','纸上谈兵十分钟，不如实战一局。'],mate:'ISFJ',mateText:'你大胆向前，对方把补给和退路都留好了。'},
    ESFP:{name:'全场气氛组',en:'THE HIGHLIGHT REEL',group:'explorer',quote:'录了吗？刚才那波录了吗！',intro:'你的游戏体验，讲究一个当场开心。赢了要庆祝，翻车也能笑出声；好看的皮肤配上好朋友，这局已经值了。跟你开黑，平平无奇的一晚也能有花絮。',tags:['名场面体质','及时行乐','自带BGM'],habits:['胜利动作和表情包都准备齐了。','高光要发，搞笑失误更得发。','比起上分，更在意今晚有没有尽兴。'],mate:'ISTJ',mateText:'对方让局面靠谱，你让这个靠谱的夜晚变有趣。'}
  };
  const q=(axis,scene,title,sub,options,reverse=false)=>({axis,scene,title,sub,options,scores:reverse?[-2,-1,1,2]:[2,1,-1,-2]});
  const questions=[
    q(0,'周五晚 · 好友列表亮了','终于下班了。今晚的游戏，你想怎么开局？','不用想“应该怎样”，选你最常做的。',['先群里喊一嗓子：缺人吗？带我一个。','看看谁在线，熟人有局就加入。','先自己玩着，有人喊再说。','把状态切成隐身，享受独处时间。']),
    q(1,'新游戏 · 第一次落地','刚进一个开放世界，你第一件事是？','地图很大，今天的时间也是你的。',['跟着新手任务走，先把基本操作练明白。','看看附近资源，先让装备像个样子。','随便走走，那座远山看起来能上去。','先研究：这世界的边界到底在哪？']),
    q(2,'组队副本 · 又团灭了','队友连续失误，大家第七次躺在地上。你会？','语音里安静了三秒。',['把失误点说清楚，重新分工再来。','提醒一下机制，建议换个打法。','先说句没事，问问是不是不熟这段。','气氛比进度重要，歇一会儿聊两句吧。']),
    q(3,'周末 · 新副本解锁','明晚要开荒，今晚的你在干什么？','离集合还有整整一天。',['查攻略、配装备，列好需要准备的东西。','大概看一下机制，至少别空手去。','到时候边打边学，也来得及。','现在研究就少了惊喜，直接盲打才带劲。']),
    q(0,'匹配队伍 · 麦克风亮了','排到了三个陌生人，队里没人说话。','这局需要一点配合。',['能打字就打字，我不太想开麦。','先听着，有必要再报点。','试着问声好，聊开了就自然了。','主动活跃一下，打着打着就熟了。'],true),
    q(1,'装备栏 · 一件奇怪的掉落','掉了把属性一般、效果很怪的武器。你会？','说明写着：“有时会发生意料之外的事。”',['赶紧试试，能不能开发一套奇怪流派。','先留着，没准和别的装备有组合效果。','跟现有装备对比一下，有提升才换。','属性不行就分解，格子还得装实用的。'],true),
    q(2,'剧情分支 · 最后的选择','最喜欢的角色做了错事，你要做个决定。','游戏把选择权交到了你手上。',['按游戏规则来，喜欢也不能例外。','先看后果，再挑影响最小的处理。','想听听原因，也许还有挽回的办法。','我舍不得，能救就一定要救。']),
    q(3,'休息日 · 打开游戏库','难得有个空闲下午，你通常怎么安排？','没有任务，没有人催。',['看心情点一个，随时换游戏也没关系。','先玩起来，想到什么再做什么。','心里大概有个目标，玩到就收工。','安排好要做的事，清完列表格外舒服。'],true),
    q(0,'高光时刻 · 极限翻盘','刚打出一波特别漂亮的操作。然后呢？','这一下，确实值得。',['立刻发群里，让大家一起看。','喊朋友来看回放，顺便复盘两句。','自己回味一下，有人问就讲。','默默保存录像，自己知道爽就够了。']),
    q(1,'主线之外 · 路边有个人','一个路人 NPC 喊住你，讲起了很久以前的事。','你的主线任务就在前面。',['先赶路吧，没任务标记应该不影响进度。','快速扫一眼，有有用的信息就记下来。','听听看，也许和这个世界的历史有关。','停下来聊完，顺便猜猜他没说出口的部分。'],true),
    q(2,'赛季末 · 双排邀请','好友想跟你上分，但你们最近配合总不太顺。','今晚时间不多，段位还差一点。',['一起玩本来就开心，分以后再上。','先问问对方想怎么打，协调一下。','可以打几把，但先说好要认真沟通。','今晚先各练各的，状态好了再一起排。'],true),
    q(3,'冒险途中 · 突然出现的岔路','正按路线跑任务，旁边冒出一个限时事件。','看起来热闹，但会打乱原来的安排。',['先把原定任务做完，避免漏掉关键步骤。','看看奖励值不值得，再决定要不要去。','时间还够，绕过去瞅瞅。','计划先放一边，错过热闹可不行。']),
    q(0,'朋友不在线 · 今晚还玩不玩','你常一起玩的朋友，今晚全都有事。','游戏还在那里等着。',['正好，可以专心推进自己的存档。','自己也能玩，慢慢逛也不错。','有点没劲，看看能不能找其他人一起。','游戏先放放，找个有人的地方聊聊。'],true),
    q(1,'卡关时刻 · 第十次尝试','同一个 Boss 卡了十次，你会怎么破局？','差那么一点，但就是过不去。',['继续练走位，把攻击节奏磨熟。','找出每次失误的位置，逐个改掉。','试着换个流派，也许打法想错了。','有没有可能：这关其实有另一种解法？']),
    q(2,'游戏落幕 · 片尾字幕','一款游戏打完了，你最想和朋友聊什么？','片尾曲还在放。',['那些角色的命运，我现在还没缓过来。','某个场景让我想起了自己的事。','哪几个设计很聪明，哪些地方可惜了。','数值、机制和关卡，这套系统做得如何。'],true),
    q(3,'关闭游戏 · 今晚到此为止','准备下线了，你会在哪个时刻停下来？','明天还可以接着玩。',['想停就停，下次打开自然知道干什么。','这一段差不多了，找个安全地方下线。','做完手上这件事，再回据点整理一下。','任务交完、背包清好，明天的路线也想好了。'],true)
  ];
  const axes=[{left:'E · 组队充电',right:'I · 独自回血'},{left:'S · 实战手感',right:'N · 脑洞探索'},{left:'T · 理性决策',right:'F · 感受优先'},{left:'J · 心里有谱',right:'P · 随心开局'}];
  function calculate(answers){
    if(answers.length!==questions.length||answers.some(a=>!Number.isInteger(a)||a<0||a>3))throw new Error('请先完成所有题目');
    const totals=[0,0,0,0];questions.forEach((q,i)=>totals[q.axis]+=q.scores[answers[i]]);
    const letters=[['E','I'],['S','N'],['T','F'],['J','P']];
    const code=totals.map((n,i)=>{const first=questions.findIndex(q=>q.axis===i);const direction=n===0?questions[first].scores[answers[first]]:n;return letters[i][direction>0?0:1];}).join('');
    return {code,totals,percentages:totals.map(n=>Math.round((n+8)/16*100))};
  }
  return {types,questions,axes,calculate};
})();
